-- ============================================================================
-- AI Gym Routine Scheduler — Supabase schema (generated by gen-sql.mjs)
-- Single-user. Run this once in the Supabase SQL editor.
--
-- Tables (§16 of the spec):
--   profile        one row, the locked user profile + program settings
--   cycle          one row, the 1..4 rotating-split counter
--   exercises      the growable movement library
--   logs           set-level training history (incl. seeded baseline)
--   measurements   §13 progress tracking (bodyweight / body fat %)
--   prescriptions  cached daily plan (engine or Claude), for fast reloads
--
-- NOTE ON ACCESS: tables are created with Row Level Security DISABLED, so the
-- project's anon key can read/write them. That is intentional for a private
-- single-user app and keeps setup friction near zero. Keep your project URL
-- and anon key reasonably private. The README explains an optional passphrase
-- lock-down if you want it.
-- ============================================================================

create extension if not exists pgcrypto;  -- for gen_random_uuid()

-- ---------------------------------------------------------------- profile --
create table if not exists profile (
  id                 text primary key default 'me',
  training_age       text,
  body_comp_goal     text,
  equipment_access   text,
  injuries           text,
  known_limiter      text,
  nutrition_context  text,
  units              text default 'kg',
  weekday_cap_min    int,
  weekend_cap_min    int,
  cardio_cap_min     int,
  reentry_days       int  default 14,
  program_start      date,
  machine_increments jsonb default '{}'::jsonb,
  updated_at         timestamptz default now()
);

-- ------------------------------------------------------------------ cycle --
create table if not exists cycle (
  id         text primary key default 'me',
  week       int  not null default 1 check (week between 1 and 4),
  updated_at timestamptz default now()
);

-- -------------------------------------------------------------- exercises --
create table if not exists exercises (
  name               text primary key,
  type               text,
  primary_muscle     text,
  secondary_muscles  jsonb default '[]'::jsonb,
  equipment          text,
  increment          numeric,
  roles              jsonb default '[]'::jsonb,
  sessions           jsonb default '[]'::jsonb,
  lateral_delt       boolean default false,
  vtaper             boolean default false,
  grip_limited       boolean default false,
  rest_low           int,
  rest_high          int,
  alts               jsonb default '[]'::jsonb,
  data_source        text default 'seeded',
  created_at         timestamptz default now()
);

-- ------------------------------------------------------------------- logs --
create table if not exists logs (
  id            uuid primary key default gen_random_uuid(),
  exercise      text not null,
  weight        numeric,
  reps          int,
  rpe           numeric,
  notes         text default '',
  date          date not null,
  session_type  text,
  week_of_cycle int,
  data_source   text default 'logged',
  created_at    timestamptz default now()
);
create index if not exists logs_exercise_idx on logs (exercise);
create index if not exists logs_date_idx     on logs (date);

-- ----------------------------------------------------------- measurements --
create table if not exists measurements (
  id           uuid primary key default gen_random_uuid(),
  date         date not null,
  bodyweight_kg numeric,
  bodyfat_pct  numeric,
  -- legacy columns, no longer written by the app (kept so old rows still load):
  waist_cm     numeric,
  shoulder_cm  numeric,
  notes        text default '',
  created_at   timestamptz default now()
);
create index if not exists measurements_date_idx on measurements (date);

-- Migration for an EXISTING synced database (safe to run repeatedly):
alter table measurements add column if not exists bodyfat_pct numeric;

-- ---------------------------------------------------------- prescriptions --
create table if not exists prescriptions (
  id           uuid primary key default gen_random_uuid(),
  date         date not null,
  session_key  text,
  payload      jsonb not null,
  source       text default 'engine',
  created_at   timestamptz default now()
);
create index if not exists prescriptions_date_idx on prescriptions (date);

-- ============================ seed: profile =================================
insert into profile (id, training_age, body_comp_goal, equipment_access,
  injuries, known_limiter, nutrition_context, units, weekday_cap_min,
  weekend_cap_min, cardio_cap_min, reentry_days, program_start)
