-- ============================================================================
-- MIGRATION: set-level ordering, station tracking, session outcome.
-- Safe to run repeatedly.
-- ============================================================================

-- Set order was previously implied by created_at, which breaks when rows sync
-- out of order. Every progression and deload rule now depends on knowing which
-- set is set one, so it is stored explicitly.
alter table logs add column if not exists set_index int;
alter table logs add column if not exists station   text;

-- Backfill from insertion order — correct for existing single-device history.
with ordered as (
  select id, row_number() over (
           partition by date, exercise order by created_at, id
         ) - 1 as ix
  from logs where set_index is null
)
update logs l set set_index = o.ix from ordered o where l.id = o.id;

create index if not exists logs_day_ex_idx on logs (date, exercise, set_index);

-- Sessions were only ever done-or-missing. Distinguish prescribed / substituted
-- / skipped so the plan view can tell you what actually happened.
create table if not exists session_status (
  date          date not null,
  session_key   text not null,
  status        text not null default 'as_prescribed'
                check (status in ('as_prescribed','substituted','skipped','partial')),
  substitutions jsonb default '[]'::jsonb,
  note          text default '',
  updated_at    timestamptz default now(),
  primary key (date, session_key)
);

-- Assist machines counter-weight the lifter: more load = easier. Progression on
-- these must move the number DOWN, so they need their own flag.
alter table exercises add column if not exists inverse_load boolean default false;
update exercises set inverse_load = true where name = 'Pull Up (Assisted)';
